		public DataSourceTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated DataSource
		 * 
		 * @return DataSource
		 */
		protected DataSource generateNewEntity() {
			DataSource entity = new DataSource( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new ConnectionInfo(),  new Boolean(true),  null,  new HashSet<>(),  new HashSet<>(),  DataSourceType.values()[0],  DataFormat.values()[0] );
			
			return( entity );
		}

